const selectors = { emailBox: "#email", passwordBox: "#pass", loginButton: "#login" };

for (const [key, value] of Object.entries(selectors)) {
  console.log(`${key.padEnd(14)} -> ${value}`);
}

console.log("keys:", Object.keys(selectors).length);

// The kernel strips types, so this cell shows the *runtime* half: undefined, silently.
const parsed = JSON.parse('{"login": {"emailBox": "#email"}}');

console.log("correct key:", parsed.login.emailBox);
console.log("typo:       ", parsed.login.emialBox);   // undefined, no error

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/day5-locators.spec.ts", `// Week 5, Day 5 — locators that survive.
//
// Two things break a locator months after you wrote it: whitespace in the markup,
// and a second element appearing with the same name. Both are demonstrated here
// against the real app, with the fix measured rather than asserted.
//
// Written by a cell in week5/day5_2.ipynb. Run it yourself:
//   npx playwright test week5/generated/day5-locators.spec.ts
import { test, expect } from "@playwright/test";

test.describe("Whitespace", () => {
  test("Step 1 — XPath text() is literal; normalize-space() is not", async ({ page }) => {
    // Markup a developer will one day reformat: a newline and padding inside <p>.
    await page.setContent(\`<p id="a">   Pay\\n     Bills   </p>\`);

    // text() compares the raw string, spaces and newline included. No match.
    await expect(page.locator('xpath=//p[text()="Pay Bills"]')).toHaveCount(0);

    // normalize-space() trims the ends and collapses every run of whitespace to
    // one space first, then compares. Match.
    await expect(page.locator('xpath=//p[normalize-space()="Pay Bills"]')).toHaveCount(1);
  });

  test("Step 2 — Playwright's own text locators normalize for you", async ({ page }) => {
    await page.setContent(\`<p id="a">   Pay\\n     Bills   </p>\`);

    // Same messy markup, no normalize-space() anywhere, and both match. Playwright's
    // text engine collapses whitespace before comparing — so normalize-space() is a
    // fix for a problem XPath has and getByText() does not. One more reason the
    // built-in locators outlive hand-written XPath.
    await expect(page.getByText("Pay Bills", { exact: true })).toHaveCount(1);
    await expect(page.locator('text="Pay Bills"')).toHaveCount(1);
  });
});

test.describe("Duplicates", () => {
  test.beforeEach(async ({ page }) => {
    await page.goto("/");
    await page.getByPlaceholder("Enter Email").fill("leela@gmail.com");
    await page.getByPlaceholder("Enter Password").fill("Leela@123");
    await page.getByRole("button", { name: "Login" }).click();
    await page.waitForURL("**/dashboard");
  });

  test("Step 3 — the dashboard says Statements twice", async ({ page }) => {
    const statements = page.getByText("Statements", { exact: true });
    await expect(statements).toHaveCount(2);

    // A locator matching 2 elements is fine to count and fine to assert on. It is
    // clicking that fails: an action needs exactly one target. Playwright calls
    // this strict mode, and it is a feature — the alternative is silently acting on
    // whichever element happened to come first in the DOM.
    const failure = await statements.click({ timeout: 3000 }).catch((e: Error) => e.message);
    expect(String(failure)).toContain("strict mode violation");
    expect(String(failure)).toContain("resolved to 2 elements");
  });

  test("Step 4 — the fix that does NOT work here", async ({ page }) => {
    // The usual advice is "narrow by the parent". On this page it fails: both
    // tiles sit in a div.card-body.text-color inside a div.col-md-8. Identical
    // ancestors, so the parent tells them apart not at all.
    await expect(
      page.locator("div.card-body").getByText("Statements", { exact: true }),
    ).toHaveCount(2);
  });

  test("Step 5 — the fixes that do work", async ({ page }) => {
    // (a) Go further up, to the enclosing card. There are three cards; the two
    //     Statements tiles live in different ones, so this is a real discriminator.
    const cards = page.locator(".card");
    await expect(cards).toHaveCount(3);
    await expect(cards.first().getByText("Statements", { exact: true })).toHaveCount(1);

    // (b) Or pick by position. Honest, and brittle: insert a tile above it and
    //     .nth(3) now points at something else. Use it when nothing else exists.
    const tiles = page.locator("p.card-text");
    await expect(tiles).toHaveCount(12);
    await expect(tiles.nth(3)).toHaveText("Statements");

    // (c) .first() silences the error without deciding anything. It is the fix you
    //     reach for at 6pm and regret in review — the test now passes whichever of
    //     the two it lands on, which means it stopped checking.
    await expect(page.getByText("Statements", { exact: true }).first()).toBeVisible();
  });
});
`);

// Expected: 5 passed. Steps 1-2 are whitespace; 3-5 are the duplicate.
await runSpec("week5/generated/day5-locators.spec.ts");

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/day5-locators.json", `{
  "login": {
    "emailBox": "input[placeholder='Enter Email']",
    "passwordBox": "input[placeholder='Enter Password']",
    "loginButton": "#login"
  },
  "dashboard": {
    "tile": "p.card-text",
    "card": ".card",
    "logoutButton": "button.btn-primary"
  }
}
`);

await writeProjectFile("week5/generated/day5-external.spec.ts", `// Week 5, Day 5 — locators in a JSON file instead of in the code.
//
// The pitch: a non-programmer can fix a selector without touching TypeScript, and
// one file shows every selector the suite depends on. Real benefits.
//
// The cost is at the bottom of this file, and it is not small. Read that before
// you do this to a real suite.
//
// Written by a cell in week5/day5_2.ipynb. Run it yourself:
//   npx playwright test week5/generated/day5-external.spec.ts
import { test, expect } from "@playwright/test";
import { readFileSync } from "node:fs";
import path from "node:path";

// A plain import, not readFileSync. This needs "resolveJsonModule": true in
// tsconfig.json — already set for this repo. Why it matters: see Step 4.
import LOCATORS from "./day5-locators.json";

test.describe("Externalised locators", () => {
  test("Step 1 — a sign-in driven entirely from JSON", async ({ page }) => {
    await page.goto("/");
    await page.locator(LOCATORS.login.emailBox).fill("leela@gmail.com");
    await page.locator(LOCATORS.login.passwordBox).fill("Leela@123");
    await page.locator(LOCATORS.login.loginButton).click();
    await page.waitForURL("**/dashboard");

    await expect(page.locator(LOCATORS.dashboard.tile)).toHaveCount(12);
    await expect(page.locator(LOCATORS.dashboard.logoutButton)).toBeVisible();
  });

  test("Step 2 — every selector in the file still matches something", async ({ page }) => {
    // Worth having as a real test. An externalised selector that quietly stops
    // matching is invisible until some unrelated test fails for a confusing reason;
    // this one names the dead key instead.
    await page.goto("/");
    for (const [key, selector] of Object.entries(LOCATORS.login)) {
      await expect(page.locator(selector), \`login.\${key} -> \${selector}\`).toHaveCount(1);
    }

    await page.locator(LOCATORS.login.emailBox).fill("leela@gmail.com");
    await page.locator(LOCATORS.login.passwordBox).fill("Leela@123");
    await page.locator(LOCATORS.login.loginButton).click();
    await page.waitForURL("**/dashboard");

    for (const [key, selector] of Object.entries(LOCATORS.dashboard)) {
      const n = await page.locator(selector).count();
      expect(n, \`dashboard.\${key} -> \${selector} matched nothing\`).toBeGreaterThan(0);
    }
  });

  test("Step 3 — the same file read at run time", async ({ page }) => {
    // The other way to load it. Looks equivalent. It is not — Step 4 shows why.
    const raw = readFileSync(path.join(__dirname, "day5-locators.json"), "utf-8");
    const runtime = JSON.parse(raw) as typeof LOCATORS;

    expect(runtime.login.emailBox).toBe(LOCATORS.login.emailBox);
    await page.goto("/");
    await expect(page.locator(runtime.login.loginButton)).toBeVisible();
  });

  test("Step 4 — the cost: a typo is no longer a compile error", async () => {
    // With the plain \`import\`, TypeScript knows the exact shape of the JSON. Write
    //     LOCATORS.login.emialBox
    // and tsc refuses to build:
    //     error TS2551: Property 'emialBox' does not exist on type
    //     '{ emailBox: string; passwordBox: string; loginButton: string; }'.
    //     Did you mean 'emailBox'?
    // Try it — uncomment the line below and run \`npx tsc --noEmit\`.
    // const oops = LOCATORS.login.emialBox;

    // JSON.parse returns \`any\`, so the same typo compiles happily and fails at run
    // time with a message about \`undefined\` — from a stack that points at the
    // locator call, not at the typo.
    const loose = JSON.parse(
      readFileSync(path.join(__dirname, "day5-locators.json"), "utf-8"),
    );
    expect(loose.login.emialBox).toBeUndefined();
    expect(LOCATORS.login.emailBox).toBe("input[placeholder='Enter Email']");

    // So: externalise if a non-programmer really will edit the file. Otherwise a
    // page class gives you the same one-place-to-edit plus autocomplete, rename
    // refactoring, and a compiler that catches the typo. JSON trades those away —
    // and \`as typeof LOCATORS\` in Step 3 only *claims* the shape, it checks nothing.
  });
});
`);

// Expected: 4 passed.
await runSpec("week5/generated/day5-external.spec.ts");
